public class Partial_with_TriageGen0Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType() {
        Partial partial = new Partial();
        partial.with(null, 1);
    }

    @Test
    public void testWith_ExistingFieldSameValue() {
        DateTimeFieldType year = DateTimeFieldType.yearOfStandardChronology();
        Partial partial = new Partial(new DateTimeFieldType[]{year}, new int[]{2020});

        // Should return 'this' if value is same
        Partial result = partial.with(year, 2020);
        assertSame("Should return the same instance if value is unchanged", partial, result);
    }

    @Test
    public void testWith_ExistingFieldDifferentValue() {
        DateTimeFieldType year = DateTimeFieldType.yearOfStandardChronology();
        Partial partial = new Partial(new DateTimeFieldType[]{year}, new int[]{2020});

        Partial result = partial.with(year, 2021);
        assertEquals(1, result.size());
        assertEquals(2021, result.getValue(0));
        assertNotSame(partial, result);
    }

    @Test
    public void testWith_AddNewField_SortedByDuration() {
        // We will use Millis, Seconds, Minutes to test the sorting logic
        // The loop compares unitField.compareTo(loopUnitField) > 0 to break (descending order of unit size)
        // Actually, the logic: if (compare > 0) break; means the loop stops when the new field's unit 
        // is "larger" than the current loop element.

        DateTimeFieldType millis = DateTimeFieldType.millisOfStandardChronology();
        DateTimeFieldType seconds = DateTimeFieldType.secondsOfStandardChronology();
        DateTimeFieldType minutes = DateTimeFieldType.minutesOfStandardChronology();

        // Start with Millis
        Partial partial = new Partial(new DateTimeFieldType[]{millis}, new int[]{100});

        // Add Seconds (Seconds > Millis, so it should be inserted at index 0)
        partial = partial.with(seconds, 30);
        assertEquals(2, partial.size());
        assertEquals(seconds, partial.getFieldType(0));
        assertEquals(millis, partial.getFieldType(1));

        // Add Minutes (Minutes > Seconds, so it should be inserted at index 0)
        partial = partial.with(minutes, 5);
        assertEquals(3, partial.size());
        assertEquals(minutes, partial.getFieldType(0));
        assertEquals(seconds, partial.getFieldType(1));
        assertEquals(millis, partial.getFieldType(2));
    }

    @Test
    public void testWith_AddNewField_CompareRangeDuration() {
        // This tests the branch: if (compare == 0) { if (fieldType.getRangeDurationType() == null) break; ... }
        // We need field types that have the same duration but different range durations.
        // In standard Joda, most standard types have different durations.
        // However, we can simulate the logic by using types where compare == 0.

        DateTimeFieldType type1 = DateTimeFieldType.yearOfStandardChronology();
        // Since we cannot easily mock the internal fields of DateTimeFieldType without heavy libraries, 
        // we rely on the fact that if we add a field that is "smaller" than existing, 
        // it should go to the end.

        Partial partial = new Partial(new DateTimeFieldType[]{DateTimeFieldType.yearOfStandardChronology()}, new int[]{2000});
        // Year is much larger than Month. Month should be inserted AFTER Year.
        DateTimeFieldType month = DateTimeFieldType.monthOfYearOfStandardChronology();

        partial = partial.with(month, 1);

        assertEquals(2, partial.size());
        // Year (large) should be at index 0, Month (small) at index 1
        assertEquals(DateTimeFieldType.yearOfStandardChronology(), partial.getFieldType(0));
        assertEquals(month, partial.getFieldType(1));
    }

    @Test
    public void testWith_InsertionPointMiddle() {
        // Order: Year, Month, Day
        DateTimeFieldType year = DateTimeFieldType.yearOfStandardChronology();
        DateTimeFieldType month = DateTimeFieldType.monthOfYearOfStandardChronology();
        DateTimeFieldType day = DateTimeFieldType.dayOfMonthOfStandardChronology();

        Partial partial = new Partial(new DateTimeFieldType[]{year, day}, new int[]{2020, 15});

        // Insert Month in the middle
        partial = partial.with(month, 6);

        assertEquals(3, partial.size());
        assertEquals(year, partial.getFieldType(0));
        assertEquals(month, partial.getFieldType(1));
        assertEquals(day, partial.getFieldType(2));
        assertEquals(2020, partial.getValue(0));
        assertEquals(6, partial.getValue(1));
        assertEquals(15, partial.getValue(2));
    }
}
